/* @lc app=leetcode id=2281 lang=kotlin */ class Solution { fun totalStrength(strength: IntArray): Int = strength.size.let { n -> 1_000_000_007L.let { M -> strength.runningFold(0L) { s, x -> (s + x) % M }.let { P -> P.runningFold(0L) { s, x -> (s + x) % M }.let { PP -> java.util.ArrayDeque<Int>().let { st -> IntArray(n).also { l -> strength.indices.forEach { i -> generateSequence { st.peekFirst()?.takeIf { strength[it] >= strength[i] } }.forEach { _ -> st.pollFirst() }.let { l[i] = st.peekFirst() ?: -1 }.let { st.addFirst(i) } } }.let { l -> java.util.ArrayDeque<Int>().let { st2 -> IntArray(n).also { r -> (n - 1 downTo 0).forEach { i -> generateSequence { st2.peekFirst()?.takeIf { strength[it] > strength[i] } }.forEach { _ -> st2.pollFirst() }.let { r[i] = st2.peekFirst() ?: n }.let { st2.addFirst(i) } } }.let { r -> strength.indices.fold(0L) { acc, i -> (acc + strength[i].toLong() % M * ((((i - l[i]).toLong() * ((PP[r[i] + 1] - PP[i + 1] + M) % M) - (r[i] - i).toLong() * ((PP[i + 1] - PP[l[i] + 1] + M) % M)) % M + M) % M)) % M }.toInt() } } } } } } } } }